import { test, expect } from '@playwright/test';

test.describe('Virus Scan Status for Uploaded Files', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display virus scan status for uploaded files', async ({ page }) => {
    // Upload a file
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('playwright/fixtures/sample.pdf');

    // Verify file name appears
    const fileNameDisplay = page.getByText('sample.pdf');
    await expect(fileNameDisplay).toBeVisible();

    // Click upload button
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Wait for upload to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/upload') && response.status() === 200
    );

    // Verify success message
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).toBeVisible();

    // Verify virus scan status is displayed
    const scanStatus = page.getByText('Virus Scan: Complete');
    await expect(scanStatus).toBeVisible();

    // Verify scan result is clean
    const scanResult = page.getByText('No viruses found');
    await expect(scanResult).toBeVisible();

    // Verify file is listed in scan results
    const fileList = page.getByRole('region', { name: 'Scan Results' });
    await expect(fileList).toBeVisible();
  });

  test('should handle virus scan failure and display appropriate error', async ({ page }) => {
    // Intercept the upload API call and simulate a virus detection
    await page.route('**/api/upload', route => {
      route.abort('failed');
    });

    // Upload a file
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('playwright/fixtures/malicious.exe');

    // Click upload button
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Wait for error response
    await page.waitForResponse(response => 
      response.url().includes('/api/upload') && response.status() === 400
    );

    // Verify error message is displayed
    const errorMessage = page.getByText('Virus detected');
    await expect(errorMessage).toBeVisible();

    // Verify scan status shows failure
    const scanStatus = page.getByText('Virus Scan: Failed');
    await expect(scanStatus).toBeVisible();

    // Verify scan result shows virus
    const scanResult = page.getByText('Virus detected: Trojan.');
    await expect(scanResult).toBeVisible();

    // Verify file is not listed in clean results
    const fileList = page.getByRole('region', { name: 'Scan Results' });
    await expect(fileList).not.toBeVisible();
  });
});
